<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import type {ArchiveRecord} from '../types';
defineProps<{record:ArchiveRecord;index:number}>();
const viewport=ref<HTMLElement>();const scale=ref(1);let observer:ResizeObserver|undefined;
onMounted(()=>{observer=new ResizeObserver(([entry])=>{if(entry&&entry.contentRect.width>0)scale.value=entry.contentRect.width/340;});if(viewport.value)observer.observe(viewport.value);});onBeforeUnmount(()=>observer?.disconnect());
</script>
<template><div ref="viewport" class="record-viewport"><article class="record-sheet" :style="{transform:`scale(${scale})`}"><header><span>汇通云 · 电子档案</span><span>信息整理页</span></header><div class="record-number">{{String(index+1).padStart(2,'0')}} / RECORD</div><h2>{{record.kind==='voucher'?'记账凭证信息':'原始单据信息'}}</h2><p class="record-caption">以下内容来自导入 / 人工复核字段</p><dl><div><dt>{{record.kind==='voucher'?'凭证号':'单据编号'}}</dt><dd>{{record.no||'未补录'}}</dd></div><div><dt>日期</dt><dd>{{record.date}}</dd></div><div><dt>客商名称</dt><dd>{{record.supplier}}</dd></div><div><dt>金额</dt><dd class="record-money">¥ {{record.amount.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}}</dd></div><div><dt>摘要 / 名称</dt><dd>{{record.summary}}</dd></div><div><dt>原始影像</dt><dd>{{record.fileId?record.fileName:'未提供原件，仅保留结构化信息'}}</dd></div></dl><div class="record-note">{{record.fileId?'PDF 导出时附入所上传的原件全部页面；本页只作信息预览。':'当前记录不包含原始文件。本页不替代正式会计凭证或原始单据。'}}</div><footer><span>浏览器本地档案 · 非法定存证</span><span>{{index+1}}</span></footer></article></div></template>
<style scoped>.record-viewport{width:100%;height:100%;overflow:hidden}.record-sheet{width:340px;height:455px;transform-origin:top left;background:#fffefa;display:flex;flex-direction:column;padding:23px 25px 17px;color:#63728b;font-family:"Microsoft YaHei",sans-serif}.record-sheet header{display:flex;justify-content:space-between;border-bottom:1px solid #e3e8ed;font-size:7px;color:#a1aab8;padding-bottom:10px}.record-number{font-size:7px;letter-spacing:1.5px;color:#99a9bd;margin-top:24px}.record-sheet h2{font-family:serif;font-size:23px;font-weight:500;letter-spacing:3px;color:#314960;margin:13px 0 9px}.record-caption{font-size:7px;color:#a2adba;margin:0 0 20px}.record-sheet dl{margin:0}.record-sheet dl>div{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid #edf0f3;font-size:8px}.record-sheet dt{width:60px;flex-shrink:0;color:#a1adbd}.record-sheet dd{margin:0;word-break:break-word;line-height:1.7}.record-money{font-size:12px!important;font-family:Arial;color:#5277a0}.record-note{padding:12px;background:#f5f7f9;font-size:7px;line-height:1.9;color:#9aabbf;margin-top:23px}.record-sheet footer{display:flex;justify-content:space-between;font-size:6px;color:#a9b4c4;margin-top:auto;border-top:1px solid #e9edf1;padding-top:10px}</style>
